  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
  VALUES (q_id, 'พอใช้', 'Fair', '(2) - สร้างสรรค์อาหารได้อย่างจำกัด ไม่ตอบโจทย์ความต้องการของผู้บริโภค - ใช้เทคนิคการประกอบอาหารได้อย่างไม่เหมาะสม ส่งผลต่อคุณภาพของอาหาร - ขาดการดูแลความปลอดภัยในกระบวนการประกอบอาหาร - การนำเสนออาหารขาดความน่าสนใจและความเหมาะสมในทุกด้าน', 2, 2);
  INSERT INTO public.assessment_options (question_id, label_th, label_en, description_th, score, sequence)
